#include <iostream>  // 引入输入输出库

int main() {  // 程序入口，类似Python的if __name__ == '__main__'
    int n = 5;  // 声明一个整数变量
    int sum = 0;
    for (int i = 1; i <= n; i++) {  // 从1加到n
        sum += i;
    }
    std::cout << "1到" << n << "的和是" << sum << std::endl;  // 输出结果
    return 0;  // 返回0表示程序正常结束
}
